USE ai_interviewer;

-- CSS 200 MCQs
-- Source: Pasted markdown(1).md
-- Difficulty mapping (source did not specify difficulty): Q1-50 = Easy, Q51-150 = Medium, Q151-200 = Hard.
-- Reviewed corrections: Q132, Q136, Q140, Q195, Q199.


-- Verification
SELECT COUNT(*) AS css_questions
FROM questions
WHERE skill = 'CSS';

SELECT COUNT(DISTINCT question) AS unique_css_questions
FROM questions
WHERE skill = 'CSS';

SELECT skill, COUNT(*) AS question_count
FROM questions
GROUP BY skill
ORDER BY skill;